#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string line;
    getline(cin, line); // read first line and ignore
    getline(cin, line); // read second line

    // Split inputLine by parentheses pattern: \([a-zA-Z_]*\)
    vector<string> splitParts;
    regex pattern("\\([a-zA-Z_]*\\)");
    sregex_token_iterator iter(line.begin(), line.end(), pattern, -1);
    sregex_token_iterator end;
    for (; iter != end; ++iter) {
        splitParts.push_back(*iter);
    }

    int longestWord = 0;
    for (const auto& segment : splitParts) {
        // Split segment by underscores
        stringstream ss(segment);
        string word;
        while (getline(ss, word, '_')) {
            if (!word.empty()) {
                longestWord = max(longestWord, (int)word.length());
            }
        }
    }

    int parenthesesCount = 0;
    int currentCount = 0;
    bool inParentheses = false;
    bool countedInParentheses = false;

    for (size_t index = 0; index < line.length(); ++index) {
        char ch = line[index];
        if (ch == '(') {
            inParentheses = true;
        } else if (ch == ')') {
            countedInParentheses = false;
            inParentheses = false;
        } else if (inParentheses && isalpha(ch)) {
            if (countedInParentheses) continue;
            parenthesesCount++;
            countedInParentheses = true;
        } else if (ch == '_') {
            countedInParentheses = false;
        }
    }

    cout << longestWord << " " << parenthesesCount << "\n";

    return 0;
}

